          ["로그인 화면과 로그인 방식 확인하기","일반 계정은 아이디 또는 이메일과 비밀번호를 입력하는 폼을 사용합니다. 소셜로 가입했다면 가입할 때 사용한 서비스의 로그인 버튼을 찾습니다.",{"src":"assets/current/login-ko.png","alt":"제품 소개와 로그인 폼이 나란히 표시된 MOTI Studio 로그인 화면","caption":"로그인 화면 예시. 왼쪽 손 모션은 제품 소개용이며, 실제 장갑의 연결 상태를 표시하지 않습니다. 작은 창에서는 로그인 폼이 우선 표시됩니다.","annotations":[{"x":58.785,"y":14.667,"width":35.139,"height":75.111,"label":"로그인 폼","description":"계정으로 로그인하거나 회원가입·계정 찾기로 이동합니다."},{"x":6.589,"y":75.222,"width":46.999,"height":7.333,"label":"시작 가이드","description":"제품 소개 아래에서 이 가이드를 엽니다."},{"x":94.436,"y":0.444,"width":4.539,"height":3.333,"label":"도움말","description":"로그인 전에도 가이드·문제 신고·업데이트를 열 수 있습니다."}],"wide":true,"displayWidth":1366,"pixelWidth":1366,"pixelHeight":900},{"entry":"앱을 실행한 뒤 로그인 화면을 확인합니다.","action":"일반 로그인 폼과 가입한 소셜 서비스의 버튼 위치를 확인합니다.","result":"어떤 로그인 방식으로 진행할지 확인했습니다. 아직 인증이 완료된 상태는 아닙니다."}],
          ["계정 정보를 입력하고 로그인하기","아이디 또는 이메일과 비밀번호를 입력합니다. 비밀번호의 눈 모양은 입력한 값을 확인할 때 사용합니다. 다음 실행에도 이 계정을 사용하려면 로그인 유지(Keep signed in)를 선택하고, 공용 PC에서는 선택 여부를 확인합니다. 로그인(Sign in)을 누르거나 가입할 때 사용한 소셜 서비스를 선택합니다. 오류가 나면 아이디·이메일과 입력 언어, 화면 안내를 확인합니다.",{"src":"assets/current/guide-login-ko.png","alt":"계정 입력·로그인 유지·로그인과 소셜 서비스 버튼","caption":"제품 UI 예시 · 로그인 폼 확대. 입력된 계정은 설명용 예시입니다.","wide":true,"displayWidth":480,"annotations":[{"x":4.167,"y":10.559,"width":91.667,"height":20.807,"label":"계정 입력","description":"아이디 또는 이메일과 비밀번호를 입력합니다."},{"x":4.167,"y":33.54,"width":91.667,"height":4.658,"label":"로그인 유지와 계정 찾기","description":"로그인 유지를 선택하거나 아이디·비밀번호 찾기로 이동합니다."},{"x":4.167,"y":53.727,"width":91.667,"height":6.522,"label":"로그인","description":"입력한 계정으로 로그인과 실행 준비를 시작합니다."},{"x":4.167,"y":68.634,"width":91.667,"height":22.05,"label":"소셜 로그인","description":"가입할 때 사용한 Google·네이버·카카오 서비스를 선택합니다."}],"pixelWidth":960,"pixelHeight":1288},{"entry":"로그인 폼에서 계정 정보를 입력합니다.","action":"로그인 유지 여부를 확인한 뒤 로그인 또는 가입한 소셜 서비스를 선택합니다.","result":"계정 인증 뒤 실행 준비가 이어집니다."}],
          ["실행 준비 안내 확인하기","계정당 PC는 최대 3대까지 등록하며, 온라인으로 Studio를 사용하는 PC는 한 번에 1대입니다. 새 PC에서 로그인하면 빈 자리에 자동 등록됩니다. 다른 PC를 사용 중이라면 전환 확인이 필요하며, 로그인만으로 기존 PC가 종료되지는 않습니다. 등록 한도나 다른 PC 사용 안내가 나오면 <a href=\"index.html?page=pc-management\" data-page=\"pc-management\">PC 등록과 다른 PC로 전환</a>에서 해당 절차를 확인합니다.",[{"src":"assets/current/pc-session-conflict-ko.png","alt":"다른 PC의 사용 정보를 보여 주고 다른 PC를 로그아웃하고 계속할지 선택하는 화면","caption":"제품 UI 예시 · 다른 PC가 사용 중일 때 나타나는 조건부 실행 준비 안내입니다. 모든 로그인에 표시되는 창은 아닙니다.","wide":true,"displayWidth":480,"annotations":[{"x":5,"y":33.0661,"width":90,"height":16.4329,"label":"현재 사용 중인 PC","description":" — 어느 PC에서 Studio를 사용하고 있는지 확인합니다."},{"x":5,"y":74.3487,"width":90,"height":8.81764,"label":"다른 PC를 로그아웃하고 계속","description":" — 기존 PC의 작업 종료를 요청합니다. 종료가 완료되면 새 PC에서 시작하며 기존 PC 등록은 유지합니다."},{"x":5,"y":87.976,"width":90,"height":8.81764,"label":"로그인으로 돌아가기","description":" — 전환을 요청하지 않고 돌아갑니다. 기존 PC에서 계속 사용할 수 있습니다."}],"pixelWidth":960,"pixelHeight":998},{"src":"assets/current/pc-limit-ko.png","alt":"등록 한도에 도달해 기존 PC 중 교체할 PC를 선택하는 화면","caption":"제품 UI 예시 · 등록 한도를 모두 사용한 경우의 교체 선택 화면입니다. 실제 계정이나 PC를 교체하지 않았습니다.","wide":true,"displayWidth":480,"annotations":[{"x":5,"y":60.4361,"width":87.0833,"height":10.9034,"label":"교체할 PC","description":" — 기존 PC에서 작업을 마치고 로그아웃한 뒤 대상을 선택합니다."},{"x":5,"y":80.0623,"width":87.0833,"height":6.85358,"label":"선택한 PC 교체","description":" — 선택한 PC의 등록 자리를 새 PC로 바꿉니다."},{"x":5,"y":90.6542,"width":87.0833,"height":6.85358,"label":"로그인으로 돌아가기","description":" — 교체를 진행하지 않고 로그인 화면으로 돌아갑니다."}],"pixelWidth":960,"pixelHeight":1284}],{"entry":"로그인 뒤 표시된 실행 준비 안내를 확인합니다.","action":"PC 한도나 다른 PC 사용 안내가 있으면 연결된 전환 절차를 따릅니다.","result":"필요한 확인과 준비가 완료된 뒤 작업공간이 열립니다."}],
          ["도움말 다시 열기","로그인 화면 오른쪽 위 도움말(Help)의 시작 가이드는 이 가이드 페이지를 엽니다. 같은 메뉴에서 문제 신고와 앱 업데이트도 열 수 있습니다.",{"src":"assets/current/help-menu-ko.png","alt":"로그인 화면 도움말 메뉴의 시작 가이드와 오류 보고 및 앱 업데이트 항목","caption":"도움말 메뉴 예시. 로그인 전에도 가이드, 오류 보고와 앱 업데이트에 접근할 수 있습니다.","compact":true,"annotations":[{"x":6.977,"y":20,"width":83.721,"height":14.359,"label":"시작 가이드","description":"이 가이드 페이지를 엽니다."},{"x":6.977,"y":34.872,"width":83.721,"height":13.846,"label":"문제 신고하기","description":"문제 제목과 설명을 작성하는 창을 엽니다."},{"x":6.977,"y":49.231,"width":83.721,"height":29.744,"label":"저장된 보고서와 설정","description":"PC에 보관된 보고서와 전송 설정을 엽니다."},{"x":6.977,"y":79.487,"width":83.721,"height":14.359,"label":"앱 업데이트","description":"현재 버전과 새 버전을 확인하는 창을 엽니다."}],"wide":true,"displayWidth":172,"pixelWidth":172,"pixelHeight":195},{"entry":"로그인 화면 오른쪽 위 도움말을 엽니다.","action":"시작 가이드·문제 신고·앱 업데이트 중 필요한 항목을 선택합니다.","result":"선택한 안내 페이지 또는 도구가 열립니다."}]
