function renderStepDetails(details, labels = {}) {
  if (!details) return "";
  return `<dl class="step-details">${[["entry", "진입 경로"], ["action", "할 일"], ["result", "결과 확인"]].filter(([key]) => details[key]).map(([key, label]) => `<div><dt>${labels[key] || label}</dt><dd>${details[key]}</dd></div>`).join("")}</dl>`;
}

function renderStepImage(image, figureId) {
  const annotations = image.annotations || [];
  const wide = image.wide || annotations.length > 0;
  const imageMarkup = `<img class="step-image${image.compact ? " step-image-compact" : ""}" src="${image.src}" alt="${image.alt}"${image.pixelWidth && image.pixelHeight ? ` width="${image.pixelWidth}" height="${image.pixelHeight}"` : ""} loading="lazy">`;
  const markers = annotations.map((annotation, index) => `<span class="image-annotation${index === 0 ? " is-active" : ""}" style="left:${annotation.x}%;top:${annotation.y}%;width:${annotation.width}%;height:${annotation.height}%" data-number="${index + 1}" aria-hidden="true"></span>`).join("");
  const toolbar = annotations.length ? `<div class="annotation-toolbar"><span class="annotation-current" aria-live="polite">1 · ${annotations[0].label}</span><button class="annotation-toggle" type="button" aria-pressed="true">표시 숨기기</button></div>` : "";
  const legend = annotations.length ? `<p class="annotation-hint">번호를 선택하면 해당 위치의 테두리만 표시합니다.</p><ol class="image-legend" aria-label="화면 위치와 동작 설명">${annotations.map((annotation, index) => `<li><button type="button" class="image-legend-button" data-annotation="${index + 1}" aria-pressed="${index === 0}"><span class="image-legend-number" aria-hidden="true">${index + 1}</span><span class="image-legend-copy"><strong>${annotation.label}</strong><span>${annotation.description.replace(/^\s*[—–-]\s*/, "")}</span></span></button></li>`).join("")}</ol>` : "";
  return `<figure class="step-figure${wide ? " step-figure-wide" : ""}" id="${figureId}" data-show-annotations="true">${toolbar}${wide ? `<a class="step-image-link"${image.displayWidth ? ` style="max-width:${image.displayWidth}px"` : ""} href="${image.src}" target="_blank" rel="noopener noreferrer" aria-label="${image.alt} 원본 보기 (새 탭)"><span class="annotated-image">${imageMarkup}${markers}</span></a>` : imageMarkup}${legend}${image.caption ? `<figcaption>${image.caption}</figcaption>` : ""}</figure>`;
}

function selectImageAnnotation(figure, number) {
  const selected = figure.querySelector(`[data-annotation="${number}"]`);
  figure.querySelectorAll(".image-legend-button").forEach((button) => button.setAttribute("aria-pressed", String(button === selected)));
  figure.querySelectorAll(".image-annotation").forEach((marker) => marker.classList.toggle("is-active", marker.dataset.number === number));
  figure.querySelector(".annotation-current").textContent = `${number} · ${selected.querySelector("strong").textContent}`;
  figure.dataset.showAnnotations = "true";
  const toggle = figure.querySelector(".annotation-toggle");
  toggle.setAttribute("aria-pressed", "true");
  toggle.textContent = "표시 숨기기";
}

function renderDocument(topic) {
  const index = topics.findIndex((item) => item.id === topic.id);
  const previous = topics[index - 1];
  const next = topics[index + 1];
  document.title = `${topic.title} · MOTI Studio Guide`;
  main.innerHTML = `
    <div class="document-view">
      <nav class="breadcrumb" aria-label="현재 위치"><a href="index.html" data-home>홈</a>${icon("chevron")}<span>${topic.category.title}</span>${icon("chevron")}<span>${topic.title}</span></nav>
      <div class="document-grid">
        <article class="document-main">
          <header>
            <div class="document-kicker"><span class="category-icon">${icon(topic.category.icon)}</span>${topic.category.title}</div>
            <h1>${topic.title}</h1>
            <p class="document-lead">${topic.summary}</p>
          </header>

          ${topic.criticalWarning ? `<div class="callout warning document-alert"><span class="callout-icon">${icon("alert")}</span><div><strong>${topic.criticalWarningLabel || "중요 경고"}</strong><p>${topic.criticalWarning}</p></div></div>` : ""}

          ${topic.hideOverview ? "" : `<section class="doc-section" id="overview"><h2>이 페이지에서 다룰 내용</h2><ul class="content-list">${topic.covers.map((item) => `<li>${item}</li>`).join("")}</ul></section>`}
          ${topic.licenseComponents ? `<section class="doc-section" id="components"><h2>구성요소별 라이선스</h2><div class="license-table-wrap"><table class="license-table"><thead><tr><th>구성요소</th><th>확인 버전</th><th>출시 패키지</th><th>라이선스</th><th>배포 전 조치</th><th>상태</th></tr></thead><tbody>${topic.licenseComponents.map((component) => `<tr><td>${component.source ? `<a href="${component.source}" target="_blank" rel="noopener noreferrer">${component.name}</a>` : component.name}</td><td>${component.version}</td><td>${component.release}</td><td>${component.license}</td><td>${component.action}</td><td><span class="license-status">${component.status}</span></td></tr>`).join("")}</tbody></table></div></section>` : ""}
          ${topic.licenseNotices ? `<section class="doc-section" id="notices"><h2>제3자 저작권 및 라이선스 고지</h2><p>다음 고지는 MOTI Studio 출시 구성에 포함된 것으로 확인된 허용적 라이선스 및 고지·소스 제공 대상 구성요소에 적용됩니다. 각 항목을 열면 저작권자, 적용 라이선스와 원문을 확인할 수 있습니다.</p><div class="license-notices">${topic.licenseNotices.map((notice) => `<details class="license-notice"><summary><span>${notice.name}</span><small>${notice.version} · ${notice.license}</small></summary><div class="license-notice-body"><p>${notice.copyright}</p><p><strong>적용 라이선스:</strong> ${notice.license}</p>${notice.term ? `<pre class="license-terms">${licenseTerms[notice.term]}</pre>` : `<p>이 항목은 라이선스 전체 조문 또는 복수 라이선스가 적용되므로 아래 원문과 원본 소스가 이 고지의 일부를 구성합니다.</p>`}<a href="${notice.source}" target="_blank" rel="noopener noreferrer">라이선스 원문 및 원본 소스 보기 ↗</a></div></details>`).join("")}</div></section>` : ""}
          ${topic.hidePrerequisites ? "" : `<section class="doc-section" id="prepare"><h2>${topic.prepareTitle || "사전 준비"}</h2><ul class="content-list">${topic.prerequisites.map((item) => `<li>${item}</li>`).join("")}</ul></section>`}
          <section class="doc-section" id="steps"><h2>${topic.stepsTitle || "사용 방법"}</h2>${(topic.stepGroups || [{ start: 0, end: topic.steps.length }]).map((group, groupIndex) => `<div class="step-group"${group.title ? ` id="step-group-${groupIndex + 1}"` : ""}>${group.title ? `<h3>${group.title}</h3>` : ""}<ol class="steps">${topic.steps.slice(group.start, group.end).map((step, stepIndex) => {
            const stepImages = Array.isArray(step[2]) ? step[2] : step[2] ? [step[2]] : [];
            return `<li class="step-card" id="step-${group.start + stepIndex + 1}"><strong>${step[0]}</strong>${step[1] ? `<span>${step[1]}</span>` : ""}${renderStepDetails(step[3], topic.stepDetailLabels)}${stepImages.length ? `<div class="step-images">${stepImages.map((image, imageIndex) => renderStepImage(image, `figure-${topic.id}-${group.start + stepIndex + 1}-${imageIndex + 1}`)).join("")}</div>` : ""}</li>`;
          }).join("")}</ol></div>`).join("")}</section>
          ${topic.hideResult ? "" : `<section class="doc-section" id="result"><h2>${topic.resultTitle || "정상 결과"}</h2><div class="callout"><span class="callout-icon">${icon("check")}</span><div><strong>${topic.resultLabel || "완료 확인"}</strong><p>${topic.result}</p></div></div></section>`}
          ${topic.packetFormatTitle ? `<section class="doc-section" id="packet-format"><h2>${topic.packetFormatTitle}</h2><div class="callout"><span class="callout-icon">${icon("check")}</span><div><strong>${topic.packetFormatTitle}</strong><p>${topic.packetFormatBody}</p></div></div></section>` : ""}
          <section class="doc-section" id="note"><h2>${topic.noteTitle || "주의사항"}</h2><div class="callout warning"><span class="callout-icon">${icon("alert")}</span><div><strong>${topic.noteLabel || "작업 전 확인"}</strong><p>${topic.note}</p></div></div></section>

          <nav class="document-footer" aria-label="이전 및 다음 문서">
            ${previous ? `<a href="${topicHref(previous.id)}" data-page="${previous.id}">← 이전 문서<strong>${previous.title}</strong></a>` : '<span class="empty"></span>'}
            ${next ? `<a href="${topicHref(next.id)}" data-page="${next.id}">다음 문서 →<strong>${next.title}</strong></a>` : '<span class="empty"></span>'}
          </nav>
        </article>
        <aside class="page-toc" aria-label="이 페이지의 목차">
          <h2>이 페이지에서</h2>
          ${topic.hideOverview ? "" : `<a href="#overview">다룰 내용</a>`}${topic.licenseComponents ? `<a href="#components">구성요소별 라이선스</a>` : ""}${topic.licenseNotices ? `<a href="#notices">저작권 및 라이선스 고지</a>` : ""}${topic.hidePrerequisites ? "" : `<a href="#prepare">${topic.prepareTitle || "사전 준비"}</a>`}<a href="#steps">${topic.stepsTitle || "사용 방법"}</a>${topic.stepGroups ? topic.stepGroups.map((group, groupIndex) => `<a class="toc-step" href="#step-group-${groupIndex + 1}">${group.title}</a>`).join("") : topic.steps.map((step, stepIndex) => `<a class="toc-step" href="#step-${stepIndex + 1}">${stepIndex + 1}. ${step[0]}</a>`).join("")}${topic.hideResult ? "" : `<a href="#result">${topic.resultTitle || "정상 결과"}</a>`}${topic.packetFormatTitle ? `<a href="#packet-format">데이터 패킷 형식</a>` : ""}<a href="#note">${topic.noteTitle || "주의사항"}</a>
        </aside>
      </div>
    </div>
  `;
  updateActiveNavigation(topic.id);
}

function updateActiveNavigation(pageId) {
  document.querySelectorAll(".sidebar-home").forEach((link) => link.classList.toggle("active", !pageId));
  document.querySelectorAll(".sidebar-topic").forEach((link) => link.classList.toggle("active", link.dataset.page === pageId));
}

function currentPageId() {
  return new URLSearchParams(window.location.search).get("page");
}

function renderRoute() {
  const pageId = currentPageId();
  const topic = topicById.get(pageId);
  if (topic) renderDocument(topic);
  else renderHome();
}

function navigateTo(pageId) {
  closeSearch();
  closeMenu();
  const url = pageId ? topicHref(pageId) : "index.html";
  history.pushState({ page: pageId || null }, "", url);
  renderRoute();
  window.scrollTo({ top: 0, behavior: "smooth" });
  main.focus({ preventScroll: true });
}

function openMenu() {
  document.body.classList.add("menu-open");
  document.getElementById("mobile-menu-button").setAttribute("aria-expanded", "true");
}

function closeMenu() {
  document.body.classList.remove("menu-open");
  document.getElementById("mobile-menu-button").setAttribute("aria-expanded", "false");
}

function renderSearch(query) {
  const normalized = query.trim().toLowerCase();
  if (!normalized) return closeSearch();
  const matches = searchEntries.filter((entry) => entry.text.includes(normalized)).map((entry) => entry.topic).sort((a, b) => Number(b.title.toLowerCase().includes(normalized)) - Number(a.title.toLowerCase().includes(normalized))).slice(0, 8);
  searchResults.innerHTML = matches.length
    ? matches.map((topic) => `<a class="search-result" href="${topicHref(topic.id)}" data-page="${topic.id}"><strong>${topic.title}</strong><span>${topic.category.title}</span></a>`).join("")
    : '<div class="search-empty">일치하는 가이드가 없습니다.</div>';
  searchResults.hidden = false;
}

function closeSearch() {
  searchResults.hidden = true;
}

document.addEventListener("click", (event) => {
  const annotation = event.target.closest("[data-annotation]");
  if (annotation) {
    selectImageAnnotation(annotation.closest(".step-figure"), annotation.dataset.annotation);
    return;
  }
  const annotationToggle = event.target.closest(".annotation-toggle");
  if (annotationToggle) {
    const figure = annotationToggle.closest(".step-figure");
    const show = figure.dataset.showAnnotations !== "true";
    figure.dataset.showAnnotations = String(show);
    annotationToggle.setAttribute("aria-pressed", String(show));
    annotationToggle.textContent = show ? "표시 숨기기" : "표시 보기";
    return;
  }
  const pageLink = event.target.closest("[data-page]");
  if (pageLink && event.button === 0 && !event.ctrlKey && !event.metaKey && !event.shiftKey && !event.altKey) {
    event.preventDefault();
    navigateTo(pageLink.dataset.page);
    return;
  }
  const homeLink = event.target.closest("[data-home]");
  if (homeLink) {
    event.preventDefault();
    navigateTo(null);
    return;
  }
  if (!event.target.closest(".global-search") && !event.target.closest(".search-results")) closeSearch();
});

searchInput.addEventListener("input", (event) => renderSearch(event.target.value));
searchInput.addEventListener("keydown", (event) => {
  if (event.key === "Escape") { closeSearch(); searchInput.blur(); }
});
document.addEventListener("keydown", (event) => {
  if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "k") { event.preventDefault(); searchInput.focus(); renderSearch(searchInput.value); }
  if (event.key === "Escape") { closeSearch(); closeMenu(); }
});
document.getElementById("mobile-menu-button").addEventListener("click", openMenu);
document.getElementById("sidebar-close").addEventListener("click", closeMenu);
document.getElementById("sidebar-scrim").addEventListener("click", closeMenu);
window.addEventListener("popstate", renderRoute);

renderSidebar();
renderRoute();
